using Offline3D;
using System.Text.Json;
using System.Diagnostics;
int count=0;void Test(string name,Action f){f();Console.WriteLine("PASS "+name);count++;}void Assert(bool b){if(!b)throw new Exception("Assertion failed");}
string root=Path.GetFullPath(args.Length>0?args[0]:"/workspace/work/large-scene-fixture");Directory.CreateDirectory(root);
IndexedGeometry Box(double width=1){var p=new[]{new Point3(),new Point3(width,0,0),new Point3(width,1,0),new Point3(0,1,0),new Point3(0,0,1),new Point3(width,0,1),new Point3(width,1,1),new Point3(0,1,1)};int[] ix={0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};var a=new IndexedMeshAccumulator();a.Append(p,Array.Empty<Point3>(),ix,MeshNormalMode.PerFace);return a.Finish();}
Matrix4 Placement(double angle,double x=0,double y=0,double z=0,bool mirror=false){double c=Math.Cos(angle),s=Math.Sin(angle),m=mirror?-1:1;return new Matrix4(c*m,-s,0,x,s*m,c,0,y,0,0,1,z,0,0,0,1);}
var material=new PlainMaterial{Name="Socket",Red=.7,Green=.7,Blue=.7};ElementIdentity Id(int i)=>new(){ElementId=i.ToString(),UniqueId="u"+i,DocumentId="host",MeshName="socket-"+i+"/0",Category="Electrical Fixtures",TypeName="Socket",Parameters=new(){{"Mark",i.ToString()}}};
void Add(SpoolSceneWriter writer,int i,IndexedGeometry g,Matrix4 t,PlainMaterial? m=null){var id=Id(i);writer.Add(id.MeshName,g,t,m??material,id);}
string small=Path.Combine(root,"placements.glb");
Test("rotated sockets share one stored mesh",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));foreach(int i in Enumerable.Range(0,3))Add(w,i,Box(),Placement(new[]{0,Math.PI/2,37*Math.PI/180}[i],i*4));var stats=w.Write(small);Assert(stats.UniqueMeshes==1&&stats.Instances==2&&stats.Triangles==36&&stats.UniqueTriangles==12);Contract.ValidateGlb(File.ReadAllBytes(small));});
Test("world positions and winding agree with legacy transformed triangles",()=>{foreach(bool mirror in new[]{false,true})foreach(double angle in new[]{0,Math.PI/2,37*Math.PI/180}){var g=Box();var transform=Placement(angle,1234567,-2345678,50,mirror);string path=Path.Combine(root,"equivalence.glb");var graphics=Matrix4.Graphics(new Point3(1234560,-2345670,50));using(var w=new SpoolSceneWriter(root,graphics)){Add(w,0,g,transform);w.Write(path);}var bytes=File.ReadAllBytes(path);Contract.ValidateGlb(bytes);var triangles=ReadTriangles(bytes);var inverseLocal=Matrix4.Graphics(new Point3()).Inverse();var expected=new List<Point3>();for(int i=0;i<g.Indices.Length;i+=3)foreach(int j in mirror?new[]{0,2,1}:new[]{0,1,2}){int v=(int)g.Indices[i+j];expected.Add(graphics.Apply(transform.Apply(inverseLocal.Apply(new Point3(g.Positions[v*3],g.Positions[v*3+1],g.Positions[v*3+2]))+g.OriginFeet)));}Assert(triangles.Count==expected.Count);for(int i=0;i<triangles.Count;i++)Assert((triangles[i]-expected[i]).Length<.000002);}});
Test("mirror prototypes stay separate with positive node transforms",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));Add(w,0,Box(),Placement(.4));Add(w,1,Box(),Placement(.4,4,mirror:true));Add(w,2,Box(),Placement(.8,8,mirror:true));Assert(w.UniqueMeshCount==2&&w.InstanceCount==1);w.Write(Path.Combine(root,"mirrors.glb"));Contract.ValidateGlb(File.ReadAllBytes(Path.Combine(root,"mirrors.glb")));});
Test("changed dimensions and materials never share incorrectly",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));Add(w,0,Box(),Placement(0));Add(w,1,Box(2),Placement(0));Add(w,2,Box(),Placement(0),new PlainMaterial{Name="Socket",Red=1,Green=0,Blue=0});Assert(w.UniqueMeshCount==3);});
Test("forced hash collisions require exact geometry byte equality",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()),_=>"collision");Add(w,0,Box(),Placement(0));Add(w,1,Box(2),Placement(0));Add(w,2,Box(),Placement(1));Assert(w.UniqueMeshCount==2&&w.InstanceCount==1);});
Test("running bounds include rotated and mirrored placements",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));Add(w,0,Box(),Placement(Math.PI/4,100));var b=w.BoundsGraphics;Assert(b[0]<30.48&&b[3]>30.48&&b[4]>b[1]);});
Test("spool files are removed after normal disposal",()=>Assert(!Directory.GetFiles(root,"*.spool").Any()));
Test("spool and partial output are removed after write failure",()=>{string path=Path.Combine(root,"nonexistent-parent",Guid.NewGuid()+".glb");try{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));Add(w,0,Box(),Placement(0));w.Write(path);throw new Exception("Expected write failure");}catch(DirectoryNotFoundException){}Assert(!Directory.GetFiles(root,"*.spool").Any());});
// A repeated curved fixture crosses the former emitted-triangle cap while its
// stored geometry remains small. The GLB is also used by the browser tests.
var points=new List<Point3>();var normals=new List<Point3>();var facets=new List<int>();const int segments=32,rings=16;
for(int y=0;y<=rings;y++)for(int x=0;x<=segments;x++){double a=x*Math.PI*2/segments,b=y*Math.PI/rings;var n=new Point3(Math.Sin(b)*Math.Cos(a),Math.Sin(b)*Math.Sin(a),Math.Cos(b));points.Add(n*.2);normals.Add(n);}
for(int y=0;y<rings;y++)for(int x=0;x<segments;x++){int a=y*(segments+1)+x,b=a+segments+1;facets.AddRange(new[]{a,b,a+1,a+1,b,b+1});}
var accumulator=new IndexedMeshAccumulator();accumulator.Append(points,normals,facets,MeshNormalMode.PerVertex);var socket=accumulator.Finish();var timer=Stopwatch.StartNew();GlbBuildStats largeStats;
Test("two million placed triangles export below the old cap using one mesh",()=>{using var w=new SpoolSceneWriter(root,Matrix4.Graphics(new Point3()));for(int i=0;i<2000;i++)Add(w,i,socket,Placement(i%4*Math.PI/2,(i%100)*3,(i/100)*3));largeStats=w.Write(Path.Combine(root,"scene.glb"));Assert(largeStats.Triangles>1500000&&largeStats.UniqueMeshes==1&&largeStats.Bytes<4000000);});
Test("strict validator accepts repeated geometry over 1.5 million triangles",()=>Contract.ValidateGlb(File.ReadAllBytes(Path.Combine(root,"scene.glb"))));
Test("stock reset restores fixed dimensions at the clicked level",()=>{var point=new Point3(42,10,-99);var b=BoxVolume.Stock(point);Assert(Math.Abs(b.Width-3.048)<1e-10&&Math.Abs(b.Depth-3.048)<1e-10&&Math.Abs(b.Above-3.048)<1e-10&&Math.Abs(b.Below-.1524)<1e-10&&b.Level==10);Assert(Math.Abs((b.MinX+b.MaxX)/2-point.X)<1e-10&&Math.Abs((b.MinZ+b.MaxZ)/2-point.Z)<1e-10);});
Test("box defaults persist metres and display units across reopen",()=>{string path=Path.Combine(root,"preferences", "box.json");var settings=new SectionBoxDefaults{SquareSizeMeters=6.096,AboveMeters=4.572,BelowMeters=.3048,Unit="meters"};settings.Save(path);var saved=SectionBoxDefaults.Load(path);Assert(saved.SquareSizeMeters==6.096&&saved.AboveMeters==4.572&&saved.BelowMeters==.3048&&saved.Unit=="meters");saved.Unit="feet";saved.Save(path);var reopened=SectionBoxDefaults.Load(path);var b=reopened.At(new Point3(25,30,-99));Assert(reopened.Unit=="feet"&&Math.Abs(b.Width-6.096)<1e-10&&b.Level==30);Assert(!Directory.GetFiles(Path.GetDirectoryName(path)!,"*.tmp").Any());});
Test("invalid preferences recover factory defaults without changing saved valid data",()=>{string path=Path.Combine(root,"preferences", "invalid.json");var valid=new SectionBoxDefaults();valid.Save(path);var bytes=File.ReadAllBytes(path);try{new SectionBoxDefaults{SquareSizeMeters=0}.Save(path);throw new Exception("Expected rejection");}catch(InvalidDataException){}Assert(bytes.SequenceEqual(File.ReadAllBytes(path)));File.WriteAllText(path,"{broken");var fallback=SectionBoxDefaults.Load(path);Assert(fallback.SquareSizeMeters==3.048&&fallback.Unit=="feet");File.WriteAllText(path,"{\"SquareSizeMeters\":-2,\"Unit\":\"meters\"}");Assert(SectionBoxDefaults.Load(path).Unit=="feet");Assert(SectionBoxDefaults.Load(path+".missing").BelowMeters==.1524);});
Test("singular matrix is rejected",()=>Reject(Mutate(small,r=>r["nodes"]![0]!["matrix"]![0]=0)));
Test("mirrored node matrices are rejected until winding is baked",()=>Reject(Mutate(small,r=>r["nodes"]![0]!["matrix"]![0]=-1)));
Test("perspective node matrices are rejected",()=>Reject(Mutate(small,r=>r["nodes"]![0]!["matrix"]![3]=.01)));
Test("sheared node matrices are rejected",()=>Reject(Mutate(small,r=>r["nodes"]![0]!["matrix"]![4]=.2)));
Test("invalid metadata references are rejected",()=>Reject(Mutate(small,r=>r["nodes"]![0]!["extras"]!["element"]=99999)));
void Reject(byte[] data){try{Contract.ValidateGlb(data);}catch(InvalidDataException){return;}throw new Exception("Expected rejection");}
byte[] Mutate(string path,Action<System.Text.Json.Nodes.JsonNode> change){var bytes=File.ReadAllBytes(path);int n=BitConverter.ToInt32(bytes,12);var r=System.Text.Json.Nodes.JsonNode.Parse(bytes.AsSpan(20,n))!;change(r);var json=System.Text.Encoding.UTF8.GetBytes(r.ToJsonString());int padded=(json.Length+3)&~3;var result=new byte[bytes.Length-n+padded];Buffer.BlockCopy(bytes,0,result,0,12);BitConverter.GetBytes(result.Length).CopyTo(result,8);BitConverter.GetBytes(padded).CopyTo(result,12);BitConverter.GetBytes(0x4e4f534a).CopyTo(result,16);Array.Fill(result,(byte)32,20,padded);json.CopyTo(result,20);Buffer.BlockCopy(bytes,20+n,result,20+padded,bytes.Length-20-n);return result;}
File.WriteAllBytes(Path.Combine(root,"identities.json"),Contract.Encode(Enumerable.Range(0,2000).Select(Id).ToArray()));
using(var d=JsonDocument.Parse(File.ReadAllBytes(small).AsMemory(20,BitConverter.ToInt32(File.ReadAllBytes(small),12))))Assert(d.RootElement.GetProperty("extras").GetProperty("revitElements")[0].GetProperty("ElementId").GetString()=="0");
Console.WriteLine(count+" indexed/spooled instancing checks passed. Large fixture time: "+timer.ElapsedMilliseconds+" ms; peak working set: "+Process.GetCurrentProcess().PeakWorkingSet64+" bytes. Linux synthetic fixture, not Revit runtime.");
List<Point3> ReadTriangles(byte[] bytes){int n=BitConverter.ToInt32(bytes,12),start=28+n;using var d=JsonDocument.Parse(bytes.AsMemory(20,n));var root=d.RootElement;var node=root.GetProperty("nodes")[0];var column=node.GetProperty("matrix").EnumerateArray().Select(v=>v.GetDouble()).ToArray();var matrix=new Matrix4(Enumerable.Range(0,16).Select(i=>column[(i%4)*4+i/4]).ToArray());var primitive=root.GetProperty("meshes")[0].GetProperty("primitives")[0];var accessors=root.GetProperty("accessors");int Offset(int i)=>root.GetProperty("bufferViews")[accessors[i].GetProperty("bufferView").GetInt32()].GetProperty("byteOffset").GetInt32();int pi=primitive.GetProperty("attributes").GetProperty("POSITION").GetInt32(),ix=primitive.GetProperty("indices").GetInt32(),offset=Offset(pi),io=Offset(ix),count=accessors[ix].GetProperty("count").GetInt32();var result=new List<Point3>();for(int i=0;i<count;i++){int v=(int)BitConverter.ToUInt32(bytes,start+io+i*4);result.Add(matrix.Apply(new Point3(BitConverter.ToSingle(bytes,start+offset+v*12),BitConverter.ToSingle(bytes,start+offset+v*12+4),BitConverter.ToSingle(bytes,start+offset+v*12+8))));}return result;}
